// Two writes to the SAME public name in the public entry. Node's real
// semantics are last-write-wins, so what this package publishes as
// `vulnerable` is safe.js's safeImpl -- never the stale first write, and
// never the same-named sibling in other.js.
exports.vulnerable = require("./dangerous").dangerousImpl;
exports.vulnerable = require("./safe").safeImpl;
exports.runOther = require("./other").vulnerable;
